import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Stage 7 — RL search policy: results","description":"","frontmatter":{"title":"Stage 7 — RL search policy: results","type":"retro","date":"2026-10-02T00:00:00.000Z"},"headers":[],"relativePath":"graphopt/project/retros/stage7-rl-results.md","filePath":"vendored/graphopt/project/retros/stage7-rl-results.md"}`),a={name:`graphopt/project/retros/stage7-rl-results.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="stage-7-—-rl-search-policy-results" tabindex="-1">Stage 7 — RL search policy: results <a class="header-anchor" href="#stage-7-—-rl-search-policy-results" aria-label="Permalink to “Stage 7 — RL search policy: results”">​</a></h1><p>Plan 0016 stage 7, the RL half (ADR 0003). The supervised policy is in <code>stage7-learned-policy-results.md</code>; this is the <em>full RL</em> player.</p><h2 id="what-was-built" tabindex="-1">What was built <a class="header-anchor" href="#what-was-built" aria-label="Permalink to “What was built”">​</a></h2><ul><li><code>catopt_core.search_env</code> — <code>SearchEnv</code> + <code>StepResult</code>: one program per episode; each step applies one rule to the e-graph; the reward is the <strong>normalized cost improvement</strong> that step produced. Bounded by <code>horizon</code>, ended early by <code>patience</code>. Torch-free, 100% covered.</li><li><code>catopt_torch.rl</code> — <code>PolicyNet</code> (scores each rule from the state plus its <strong>structural</strong> vector), <code>RLPolicy</code> (the <code>Policy</code> port), <code>train_reinforce</code> (<strong>REINFORCE</strong> with a running-mean baseline).</li><li><code>lab/train/train_rl_policy.py</code> — trains on the GPU, then races the players on held-out programs.</li></ul><h2 id="measured-result" tabindex="-1">Measured result <a class="header-anchor" href="#measured-result" aria-label="Permalink to “Measured result”">​</a></h2><p>RTX 2050, <code>torch 2.14.0+cu130</code>, 2000 episodes, horizon 6; held-out chains with shapes 2–7 (unseen in training):</p><table tabindex="0"><thead><tr><th>player</th><th>mean final cost</th></tr></thead><tbody><tr><td>random</td><td>377.0</td></tr><tr><td>declaration</td><td>377.0</td></tr><tr><td>no-op (no moves)</td><td>377.0</td></tr><tr><td>greedy (one-step oracle)</td><td><strong>361.0</strong></td></tr><tr><td><strong>rl</strong></td><td><strong>361.0</strong></td></tr></tbody></table><p>The RL policy <strong>matches the one-step cost-model oracle</strong> and beats random, declaration-order and doing nothing. It learned the associativity move from reward alone — no labels.</p><h2 id="honest-limits" tabindex="-1">Honest limits <a class="header-anchor" href="#honest-limits" aria-label="Permalink to “Honest limits”">​</a></h2><ul><li><strong>The oracle is reachable here.</strong> <code>greedy</code> is the one-step cost-model oracle from the current state (<code>rule_samples</code>), so no learned policy can beat it on this board; matching it is the available win. The interesting regime — where 1-step lookahead is myopic — needs deeper chains, and is not measured yet.</li><li><strong>Shallow credit.</strong> The reward is the immediate normalized improvement; discounting carries it across a 6-step episode but there is no learned value baseline beyond the running mean.</li><li><strong>No action masking.</strong> The action space is every rule; rules that cannot fire simply yield zero reward. Masking would sharpen the signal.</li><li><strong>One family.</strong> Chains only. Mixed families diluted the <em>supervised</em> policy (see the stage-7 retro); the RL policy has not been tested on them.</li><li><strong>Still only a player.</strong> The policy orders legal moves; the certificate still decides correctness. Nothing here can make a program wrong.</li></ul><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to “Reproduce”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">.venv/bin/python</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> lab/train/train_rl_policy.py</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --device</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> cuda</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> \\</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;">    --episodes</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 2000</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --train</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 60</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --horizon</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 6</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> --hidden</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#005CC5;"> 64</span></span></code></pre></div>`,12)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};